prompt --application/shared_components/user_interface/templates/region/folder_tab
begin
wwv_flow_imp_shared.create_plug_template(
 p_id=>wwv_flow_imp.id(337550765997668034)
,p_layout=>'TABLE'
,p_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<section class="amc-TFolderTab #REGION_CSS_CLASSES#" id="#REGION_STATIC_ID#" #REGION_ATTRIBUTES# aria-labelledby="#REGION_STATIC_ID#_heading">',
'  <header class="amc-TFolderTab-head">',
'    <div class="amc-TFolderTab-tab">',
'      <span class="amc-TFolderTab-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span>',
'      <h2 class="amc-TFolderTab-title" id="#REGION_STATIC_ID#_heading">#TITLE#</h2>',
'    </div>',
'    <div class="amc-TFolderTab-actions">#HELP##EDIT##CHANGE##COPY##DELETE##CREATE#</div>',
'  </header>',
'  <div class="amc-TFolderTab-folder">',
'    <div class="amc-TFolderTab-paper">',
'      <div class="amc-TFolderTab-body">#BODY##SUB_REGIONS#</div>',
'      <footer class="amc-TFolderTab-footer">#PREVIOUS##CLOSE##NEXT#</footer>',
'    </div>',
'  </div>',
'</section>'))
,p_page_plug_template_name=>'AMC Folder Tab'
,p_internal_name=>'AMC_TPL_FOLDER_TAB'
,p_css_file_urls=>'#APP_FILES#amc-templates/amc-tpl-folder-tab.css'
,p_theme_id=>42
,p_default_label_alignment=>'RIGHT'
,p_default_field_alignment=>'LEFT'
,p_translate_this_template=>'N'
,p_template_comment=>'Region template shaped like a file folder. The region title and icon sit on the folder tab; buttons in Help, Edit, Change, Copy, Delete and Create sit beside the tab, and Previous, Close and Next in the paper''s footer. The body is a sheet of paper with a light grain and is never clipped or transformed, so report menus, date pickers and popups work normally. Template options: Primary, Success or Danger tab color the whole folder with that palette color and switch the tab text to its contrast color; Stacked papers shows two more sheets peeking out behind the paper; Ink outline gives folder, tab and paper a bold ink border with a hard offset shadow; No body padding lets reports run edge to edge. Forced-colors mode draws plain system borders.'
);
end;
/
